import { useParams, useLocation, useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import Footer from "../Footer";
import "../Home/BlogHomeSection.css";
import "./ArticlePage.css";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Helmet } from "react-helmet-async";

const ArticlePage = () => {
  const { id: paramId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  // support both /Blog/:id and ?id= format
  const searchParams = new URLSearchParams(location.search);
  const id = paramId || searchParams.get("id");

  const articles = useSelector((state) => state.articles?.articles || []);
  const article = articles.find((a) => String(a.id) === String(id));

  if (!article) {
    return (
      <div className="article-notfound">
        <p>Articolo non trovato.</p>
        <button onClick={() => navigate(-1)}>Torna indietro</button>
      </div>
    );
  }

  const imgSrc = article.thumb || "/thumb_01.jpeg";

  return (
    <div>
      <Helmet>
        <title>{article.title} | Olio Ruocco</title>
        <meta name="description" content={article.excerpt} />
        <meta property="og:title" content={article.title} />
        <meta property="og:description" content={article.excerpt} />
        <meta property="og:image" content={`/blog/${article.thumb}`} />
      </Helmet>

      <section className="blog-home-section article-section">
        <div className="article-container">
          <div className="article-hero">
            <img
              src={imgSrc}
              alt={article.title}
              className="article-hero__image"
            />
          </div>
          <div className="article-content">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>
              {article.content}
            </ReactMarkdown>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default ArticlePage;
