import React, { useState, useEffect, useRef } from "react";

//styles
import "./infoPages.css";
import { Card, CardContent, Typography } from "@mui/material";
import TouchAppIcon from '@mui/icons-material/TouchApp';

const CARDS_CONTENT = [
  {
    title: "Passione",
    text: "L'azienda è guidata dalla passione per l'olivicoltura e dal rispetto per le piante. I componenti del gruppo, difatti, nutrono da sempre una magica ammirazione verso le caratteristiche dell’ulivo, la cui resilienza e maestosità assumono un fascino ancestrale ai nostri occhi.",
  },
  {
    title: "Condivisione",
    text: "Olio Ruocco nasce e viene gestito a livello familiare. Al suo interno i vari componenti collaborano e si confrontano per cercare di arricchire l’intero progetto con le proprie impressioni e conoscenze. La condivisione si consuma, dunque, sia nella fase di ideazione che in quella pratica del lavoro quotidiano.",
  },
  {
    title: "Autenticità",
    text: "Il nostro progetto vuole mantenere una forma di coerenza con il territorio in cui si inserisce. La montagna, infatti, non sa dire bugie. Il nostro desiderio è quello di custodire questa sensazione in ogni goccia del nostro Olio e trasmetterla alla tavola del consumatore finale.",
  },
  {
    title: "Creatività",
    text: "Questa è il faro di tutte le nostre azioni. Il nostro fine è quello di offrire al cliente il miglior prodotto possibile. Nel farlo, però, vogliamo goderci l’intero processo e non rinunciare mai alla componente divertimento. Per far si che ciò possa tramutarsi in realtà è necessario che la voglia di innovare ed adottare un approccio creativo non si spenga.",
  },
  {
    title: "Sostenibilità",
    text: "Il nostro Olio nasce dalla natura e pertanto di essa vuole avere rispetto. In linea con questa visione abbiamo deciso di seguire la strada del Biologico per la fase di produzione. Gli interventi in campo sono quindi limitati e condotti solo con prodotti consentiti dalle normative. A tutela del consumatore e dell’ambiente la nostra azienda, con scadenze periodiche, è sottoposta a controllo da parte di un ente qualificato.",
  },
];

const OurValuesCards = () => {
  const [flipped, setFlipped] = useState({});
  const [hovered, setHovered] = useState({});
  const [supportsHover, setSupportsHover] = useState(false);
  const backRefs = useRef([]);
  const [cardHeights, setCardHeights] = useState({});

  useEffect(() => {
    const measure = () => {
      const heights = {};
      for (let i = 0; i < CARDS_CONTENT.length; i++) {
        const el = backRefs.current[i];
        if (el) heights[i] = el.offsetHeight;
      }
      setCardHeights(heights);
    };

    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setSupportsHover(mq.matches);
    update();
    if (mq.addEventListener) mq.addEventListener("change", update);
    else mq.addListener(update);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", update);
      else mq.removeListener(update);
    };
  }, []);

  const toggleFlip = (i) => {
    setFlipped((prev) => ({ ...prev, [i]: !prev[i] }));
  };

  const renderCards = () => {
    let cards = [];
    for (let i = 0; i < CARDS_CONTENT.length; i++) {
      cards.push(
        <div
          key={i}
          className={`flip-card ${(flipped[i] || hovered[i]) ? "flipped" : ""}`}
          onClick={() => toggleFlip(i)}
          onMouseEnter={supportsHover ? () => setHovered((prev) => ({ ...prev, [i]: true })) : undefined}
          onMouseLeave={supportsHover ? () => setHovered((prev) => ({ ...prev, [i]: false })) : undefined}
          onMouseDown={(e) => e.preventDefault()}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              toggleFlip(i);
            }
          }}
          style={{
            minHeight: cardHeights[i] ? `${cardHeights[i]}px` : undefined,
            marginBottom: cardHeights[i] ? `${Math.round(cardHeights[i] * 0.2)}px` : undefined,
            outline: "none",
            WebkitTapHighlightColor: "transparent",
          }}
        >
          <div className="flip-card-inner">
            <div className="flip-card-front">
              <Card
                sx={{
                  margin: 0,
                  borderBottom: "3px solid #a6c6ca",
                  position: "relative",
                }}
              >
                <TouchAppIcon sx={{ position: 'absolute', fontSize: 140, top: '50%', left: '50%', transform: 'translate(-50%, -50%)', color: '#a6c6ca3a', pointerEvents: 'none' }} />
                <CardContent sx={{ position: "relative", zIndex: 1 }}>
                  <Typography
                    gutterBottom
                    variant="h5"
                    component="div"
                    style={{
                      position: "absolute",
                      top: "50%",
                      left: "50%",
                      transform: "translate(-50%, -50%)",
                      width: "100%",
                      textAlign: "center",
                      fontSize: "22px",
                      fontWeight: "600",
                      marginBottom: "12px",
                      color: "#262626ff",
                    }}
                  >
                    {CARDS_CONTENT[i].title}
                  </Typography>
                  {<Typography variant="body2" component="p" sx={{ color: "text.secondary" , visibility:  "hidden"   }}>
                    {CARDS_CONTENT[0].text}
                  </Typography>}
                </CardContent>
              </Card>
            </div>

            <div className="flip-card-back">
              <Card
                ref={(el) => (backRefs.current[i] = el)}
                sx={{
                  margin: 0,
                  borderBottom: "3px solid #a6c6ca",
                  position: "relative",
                }}
              >
                <TouchAppIcon sx={{ position: 'absolute', fontSize: 140, top: '50%', left: '50%', transform: 'translate(-50%, -50%)', color: '#a6c6ca00', pointerEvents: 'none' }} />
                <CardContent sx={{ zIndex: 1 }}>
                  <Typography variant="body3" component="p" sx={{ color: "text.secondary", textAlign: "justify" }}>
                    {CARDS_CONTENT[i].text}
                  </Typography>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      );
    }
    return cards;
  };

  return <div className="ourValuesGrid">{renderCards()}</div>;
};
export default OurValuesCards;
