import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { navigateTo } from "../../utils";
import BlogCard from "../Blog/BlogCard";
import { useDispatch, useSelector } from "react-redux";
import { setArticles } from "../../Reducers/articles";

import "./BlogHomeSection.css";
import { loadArticles } from "../../utils/loadArticles";

const BlogHome = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const articles = useSelector((state) => state.articles.articles || []);

  useEffect(() => {
    loadArticles().then((data) => {
      dispatch(setArticles(data));
    });
  }, []);

  return (
    <section className="blog-home-section">
      {/* Header */}
      <div className="blog-home-header">
        <div className="blog-home-header__left">
          <h2 className="blog-home-title">Spunti dal blog</h2>
        </div>
        <button
          className="blog-home-link"
          onClick={() => navigateTo(navigate, "/Blog")}
        >
          Vai al Blog
        </button>
      </div>

      {/* Responsive grid */}
      <div className="blog-home-grid">
        {articles && articles.length > 0
          ? articles
              .slice(-3)
              .reverse()
              .map((a) => (
                <BlogCard
                  key={a.id}
                  title={a.title}
                  excerpt={a.excerpt}
                  image={a.thumb}
                  onClick={() => navigateTo(navigate, `/Blog/${a.id}`)}
                />
              ))
          : [0, 1, 2].map((i) => <BlogCard key={i} />)}
      </div>
    </section>
  );
};

export default BlogHome;
