import React from "react";
import { Helmet } from "react-helmet-async";
import HomeHeader from "./HomeHeader";
import CatalogHome from "./CatalogHome";
import MidHome from "./MidHome";
import FAQComponent from "./FAQComponent";
import BlogHome from "./BlogHome";

import "./Home.css"
import Footer from "../Footer";
const HomePage = () => {
  return (
    <div className="homeContainer">
      <Helmet>
        <title>Olio Ruocco – Olio Extravergine di Oliva Biologico dalla Campania</title>
        <meta name="description" content="Scopri Olio Ruocco: olio extravergine di oliva biologico prodotto in Campania, Avellino, Montemarano 83040. Linee monocultivar Ravece, Leccino e Multicultivar, estratte a freddo." />
      </Helmet>
      {<HomeHeader></HomeHeader>}
      <CatalogHome></CatalogHome>
      <MidHome></MidHome>
      <FAQComponent />
      <BlogHome />
      <Footer/>
    </div>
  );
};

export default HomePage;
