import React from "react";
import { Helmet } from "react-helmet-async";
import { useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import BlogCard from "./BlogCard";
import "../Home/BlogHomeSection.css";
import Footer from "../Footer";

const extractExcerpt = (html = "", words = 30) => {
  const text = html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  return text.split(" ").slice(0, words).join(" ") + (text.split(" ").length > words ? "..." : "");
};


const Blog = () => {
  const articles = useSelector((state) => state.articles?.articles || []);
  const navigate = useNavigate();
  return (
    <>
      <Helmet>
        <title>Blog – Olio Ruocco</title>
        <meta name="description" content="Leggi gli articoli di Olio Ruocco sull'olio extravergine di oliva: consigli, curiosità e approfondimenti sulla produzione e conservazione dell'olio EVO." />
      </Helmet>
      <section className="blog-home-section">
        <h1
          className="blog-home-title"
          style={{ textAlign: "center", margin: "3rem 0 1rem 0" }}
        >
          Il Nostro Blog
        </h1>

        <div style={{ height: "1rem" }} />

        <div className="blog-home-grid">
          {articles && articles.length > 0 ? (
                  articles
                    .slice()
                    .reverse()
                    .map((a) => (
                      <BlogCard
                        key={a.id}
                        title={a.title}
                        excerpt={extractExcerpt(a.content, 28)}
                        image={a.thumb }
                        onClick={() => navigate(`/Blog/${a.id}`)}
                      />
                    ))
          ) : (
            <p style={{ gridColumn: "1/-1", textAlign: "center" }}>
              Nessun articolo disponibile.
            </p>
          )}
        </div>
      </section>
      <Footer />
    </>
  );
};

export default Blog;
