import { useMediaQuery } from "@mui/material";
import "./AboutSection.css";
import { useNavigate } from "react-router-dom";
import { navigateTo } from "../../utils";

const InfoCards = () => {
  const navigate = useNavigate();
  const isMobile = useMediaQuery("(max-width: 768px)");

  const goToAboutUs = () => navigateTo(navigate, "/AboutUs");
  const goToArtPage = () => navigateTo(navigate, "/Etichette");

  return (
    <section className="about-section">
      {/* Section header */}
      <div className="about-header">
        <h2 className="about-title">Scopri chi siamo</h2>
      </div>

      {/* Two-column responsive grid */}
      <div className="about-cards-grid">
        {/* Card 1 – Chi Siamo */}
        <div
          className="about-card"
          style={{ backgroundImage: `url("${isMobile ? "/card_2_xs.png" : "/card_2.jpg"}")` }}
        >
          <div className="about-card__content">
            <p className="about-card__label">Chi Siamo</p>
            <button className="about-card__btn" onClick={goToAboutUs}>
              Scopri di più
            </button>
          </div>
        </div>

        {/* Card 2 – Arte & Olio */}
        <div
          className="about-card"
          style={{ backgroundImage: 'url("/card_1.png")' }}
        >
          <div className="about-card__content">
            <p className="about-card__label">Etichette D’Autore</p>
            <button className="about-card__btn" onClick={goToArtPage}>
              Scopri di più
            </button>
          </div>
        </div>
      </div>
    </section>
  );
};

export default InfoCards;
