import React from "react";
import "../Home/BlogHomeSection.css";

const BlogCard = ({ title, image, excerpt, onClick }) => {
  const imgSrc = image || "/blog_home_test768x432.jpeg";

  return (
    <article className="blog-card" onClick={onClick} role={onClick ? "button" : undefined}>
      <img
        className="blog-card__image"
        src={imgSrc}
        alt={title || "Immagine articolo del blog"}
      />
      <div className="blog-card__body">
        <h3 className="blog-card__title">{title || "Titolo Articolo"}</h3>
        {excerpt ? <p className="blog-card__excerpt">{excerpt}</p> : null}
      </div>
    </article>
  );
};

export default BlogCard;
